custom_css:
/* 春芽 v1.0 2025-12-18
   作者：咩野(DC@lambkinling)
   请勿二传二改，倒卖&商用引流司马 */

:root {
  --混合: color-mix(in srgb, var(--SmartThemeBorderColor) 40%, #fff);
  --下划线: color-mix(in srgb, var(--SmartThemeUnderlineColor) 20%, #fff);
}

/* ===== 文本样式 ===== */
/* 对话 */
q {
  position: relative;
  background-image: linear-gradient(
    to right,
    transparent 0%,
    var(--下划线) 25px,
    var(--下划线) calc(100% - 25px),
    transparent 100%);
  background-repeat: repeat-x;
  background-position: 0 78%;
  background-size: 100% 0.55em;
}

/* 斜体 */
em {
  color: #fff !important; 
  text-shadow: 
    0 0 1px var(--SmartThemeEmColor), 
    0 0 2.5px var(--SmartThemeEmColor);
}

/* 删除 */
del {
  color: var(--SmartThemeUnderlineColor);
  text-decoration-color: crimson;
}

/* 代码块 */
code {
  color: #ffffff;
  background: var(--SmartThemeBorderColor);
  border: none;
  box-shadow:
    1px 1px 2px var(--SmartThemeBorderColor),
    0 0 4px var(--混合) !important;
}

.mes pre code {
  background: #fff;
  border-radius: 5px;
  border: none;
  outline: 1px dashed var(--SmartThemeBorderColor);
  outline-offset: -4px;
  box-shadow:
    1px 1px 3px var(--SmartThemeBorderColor),
    0 0 4px var(--SmartThemeBorderColor) !important;
}

/* md引用文本 */
blockquote {
  background: linear-gradient(to right, #fff,  transparent) !important;
  border-color: var(--SmartThemeEmColor) !important;
}

/* ----- 代码块内文字(没抓取完整) ----- */
.hljs {
  color: var(--SmartThemeBodyColor) !important;
  font-size: var(--mainFontSize) !important;
  line-height: 1.6;
}

/* md标题 */
.hljs-section {
  color: var(--SmartThemeEmColor) !important;
}

/* md粗体 */
.hljs-strong {
  color: var(--SmartThemeQuoteColor) !important;
}

hr {
  background: color-mix(in srgb, var(--SmartThemeBorderColor) 75%, transparent);
}

/* 选中文字高亮 */
::selection {
  background: color-mix(in srgb, var(--SmartThemeQuoteColor) 50%, white);
  color: var(--SmartThemeBodyColor);
}

/* ===== 滚动条 ===== */
::-webkit-scrollbar {
  width: 4px;
}

::-webkit-scrollbar-thumb {
  background:
    linear-gradient(135deg, var(--SmartThemeBorderColor) 0%, var(--SmartThemeBlurTintColor) 100%);
  border: 0.2px solid var(--SmartThemeBorderColor) !important;
  box-shadow: none !important;
}

/* 隐藏移动端聊天区域滚动条 */
@media (max-width: 768px) {
  #chat::-webkit-scrollbar {
    display: none;
  }
}

/* ----- 滑动条 ----- */
input[type="range"] {
  background: 
    linear-gradient(185deg, var(--SmartThemeBorderColor) 0%, var(--SmartThemeBlurTintColor) 100%) !important;
  border-radius: 15px !important;
  height: 5px !important;
  filter: none !important;
  box-shadow: 
    1px 1px 1px var(--混合),
    -1px -1px 1px rgba(197, 197, 197, 0.1) !important;
}

input[type="range"]::-webkit-slider-thumb {
  filter: none !important;
  background: 
    linear-gradient(135deg, var(--SmartThemeBorderColor) 0%, var(--SmartThemeBlurTintColor) 100%);
  border-radius: 50%;
  border: none;
  box-shadow: 
    1px 1px 1px rgba(0, 0, 0, 0.2),
    -1px -1px 1px rgba(197, 197, 197, 0.1);
}

/* ===== 顶栏 ===== */
#top-bar,
body.no-blur #top-bar {
  box-shadow: none !important;
  outline: 1px solid var(--SmartThemeBlurTintColor) !important;
}

.drawer-icon.fa-fw {
    display: flex;
    overflow: visible;
    justify-content: center;
    font-size: calc(var(--mainFontSize) * 1.35);
}

/* 顶栏图标 */
.drawer-icon:not(.redOverlayGlow)::before,
#leftNavDrawerIcon::before,
#rightNavDrawerIcon::before{
  font-family: "Font Awesome 6 Free";
  content: "🌲";
  color: var(--SmartThemeBorderColor);
}

/* 树叶 */
#API-status-top:not(.redOverlayGlow)::before,
#WI-SP-button .drawer-icon::before,
#backgrounds-drawer-toggle .drawer-icon::before,
#persona-management-button .drawer-icon::before {
  content: "🌱";
}

#API-status-top.redOverlayGlow::before {
  content: "\f54c" !important;
}

.drawer-icon:not(.redOverlayGlow):hover::before,
#leftNavDrawerIcon:hover::before,
#rightNavDrawerIcon:hover::before {
  color: var(--SmartThemeQuoteColor);
  opacity: 0.75;
}

#API-status-top:not(.redOverlayGlow):hover::before,
#WI-SP-button .drawer-icon:hover::before,
#backgrounds-drawer-toggle .drawer-icon:hover::before,
#persona-management-button .drawer-icon:hover::before {
  color: var(--SmartThemeEmColor);
  opacity: 0.75;
}

.drawer-icon.fa-fw:hover {
  animation: gentleSway 1.2s ease-in-out infinite alternate;
}

@keyframes gentleSway {
  0% { 
    transform: rotate(-3deg) translateY(0);
    filter: drop-shadow(0 0 3px rgba(106, 153, 78, 0.75));
  }
  100% { 
    transform: rotate(3deg) translateY(-2px);
    filter: drop-shadow(0 0 6px rgba(86, 124, 45, 0.75));
  }
}

/* top-bar插件 */
#extensionTopBar {
  border-radius: 0 !important;
}

/* 底栏宽度 */
#send_form {
  width: 92%;
}

#send_form, 
body.no-blur #send_form {
  border-radius: 5px;
  padding: 3px;
  border: 1.8px solid var(--SmartThemeBorderColor) !important;
  outline: 2.5px solid var(--SmartThemeBlurTintColor) !important;
  box-shadow:
    2px 2px 4px var(--SmartThemeBorderColor),
    0 0 6px var(--SmartThemeBorderColor);
}

#send_textarea {
    clip-path: none !important;
    box-shadow: none !important;
    border: none;
}

#send_form textarea:focus {
  box-shadow: 
    1px 1px 2.5px var(--混合),
    inset 0 0 15px var(--SmartThemeBlurTintColor);
  background-color: color-mix(in srgb, var(--SmartThemeBorderColor) 15%, #fff);
}

/* 底栏图标 */
#quick-reply-rocket-button,
#send_form .fa-solid {
  font-size: calc(var(--mainFontSize) * 1.5);
  color: var(--SmartThemeBorderColor);
}

#options_button::before {
    content: "\f4d8";
}

#extensionsMenuButton::before {
    content: "\f06c";
}

#send_but::before {
    content: "\f124";
    transform: rotate(270deg);
}

#mes_stop i::before {
    content: "\f05e";
    color: crimson;
}

/* 输入框文案自定义 */
#send_textarea::placeholder {
    opacity: 0;
}

#nonQRFormItems {
    position: relative;
    display: flex;
    align-items: center;
}

/* 📍输入框文案 */
#nonQRFormItems::before {
    content: "₊⁺♡๑ 春日来信 ₊⁺☘︎ ⑅";
    position: absolute;
    left: calc(50% + 10px); /* 左右位置 */
    top: 50%;
    transform: translate(-50%, -50%);
    font-size: calc(var(--mainFontSize) * 0.9);
    color: var(--SmartThemeBorderColor);
    pointer-events: none;
    z-index: 1;
}

#nonQRFormItems:has(#send_textarea:focus)::before,
#nonQRFormItems:has(#send_textarea:not(:placeholder-shown))::before {
    display: none !important;
}

/* 底栏悬浮 by NAKARI */
#form_sheld {
  position: absolute;
  bottom: 10px;  /* 底栏与输入框距离 */
}

#chat {
  max-height: calc(100dvh + var(--bottomFormBlockSize));
  height: calc(100dvh + var(--bottomFormBlockSize));
}

/* 当 textarea 聚焦或有内容时 */
#form_sheld:has(#send_textarea:focus),
#form_sheld:has(#send_textarea:not(:placeholder-shown)) {
  position: sticky;
}

/* 底栏菜单列表 */
.list-group,
.options-content,
#options {
  box-shadow: none !important;
}

/* quickPersona */
#quickPersonaImg {
    box-shadow: none !important;
}

.list-group-item .quickPersonaMenuImg {
    box-shadow: none;
    border: none;
}

/* qr */
#qr--bar > .qr--buttons .qr--button {
  border: none !important;
  border-radius: 2px !important;
  background: transparent;
  box-shadow:
    1px 1px 2px var(--SmartThemeBorderColor),
    0 0 2px var(--SmartThemeBorderColor) !important;
}

/* ===== 消息区域 ===== */
#chat {
  border: none;
}

/* ----- 欢迎页 ----- */
.welcomePanel {
  background: none !important;
  border: none !important;
}

.welcomePanel .recentChatList .recentChat {
    margin-bottom: 10px;
    border-radius: 5px;
    background-color: var(--SmartThemeBlurTintColor);
    outline: 1.5px solid var(--SmartThemeBlurTintColor) !important;
    box-shadow: 0 0 3px 1px var(--SmartThemeBorderColor);
}

/* 为编辑按钮区域留出空间 */
.chatNameContainer {
    padding: 1px 3.5px;
}

/* 欢迎页按钮 */
.mes_button.showRecentChats .fa-circle-chevron-down,
.mes_button.hideRecentChats .fa-circle-xmark {
  color: var(--SmartThemeEmColor);
  opacity: 1 !important;
}

.mes_button.showRecentChats .fa-circle-chevron-down::before {
  content: "\f4d8";
}

.mes_button.hideRecentChats .fa-circle-xmark::before {
  content: "\f1bb";
  color: var(--SmartThemeQuoteColor);
}

/* --- 思维链 --- */
.mes_reasoning_header {
    background-color: transparent;
    margin: 0 auto;
}

.mes_reasoning_arrow {
  display: none;
}

/* 📍思维链文字自定义 */
.mes_reasoning_header_title {
  font-size: 0;
  &::before {
    content: "₊ 𖧷˖ 𝓢𝓹𝓻𝓲𝓷𝓰 𝓓𝓪𝔂 𝓛𝓮𝓽𝓽𝓮𝓻 ˖𖧷 ₊";
    font-size: calc(var(--mainFontSize) * 0.9);
    color: var(--SmartThemeEmColor);
    border-radius: 5px;
    padding: 2px 6px;
    box-shadow:
      0 0 2.5px var(--混合),
      1px 1px 2.5px var(--混合),
      inset 0 0 12px #fff;
  }
}

@media (max-width: 768px) {
  .mes_reasoning_details {
    position: relative;
}

  .mes_reasoning_details[open] {
  width: 100%;
}

  .mes_reasoning {
    width: 100%;
    max-height: 500px; /* 内容高度 */
    overflow: hidden auto;
    font-size: calc(var(--mainFontSize) * 0.9);
    border-radius: 8px;
    border: 1px dotted var(--SmartThemeBorderColor);
    background: color-mix(in srgb, var(--SmartThemeUnderlineColor) 15%, #fff);
  }

  .mes_reasoning_actions {
     position: absolute;
     right: 5px;
     top: 5px;
     z-index: 10;
     flex-shrink: 0;
     padding: 0 5px;
  }
}

/* 消息框 */
.last_mes {
  margin-bottom: 60px !important;
}

.last_mes[is_user="false"] .mes_block {
  margin-bottom: 40px !important;
}

.mes {
  flex-direction: column;
  position: relative;
  width: 95%;
  margin: 30px 0 0 auto;
  padding: 10px 10px 0 !important;
  border: none !important;
  border-radius: 15px 0 0 15px !important;
  color: #424c56 !important;
  box-shadow:
    0 0 2px var(--SmartThemeBorderColor),
    1px 1px 5px var(--混合),
    inset 0 0 2vh rgba(255, 255, 255, 0.75);
}

.mes[is_user="false"] {
  padding: 10px!important;
  margin: 30px auto 0 0;
  border-radius: 0 15px 15px 0 !important;
}

.mes[is_user="true"]::before {
  content: "";
  white-space: pre-wrap;
  position: absolute;
  bottom: 10px;
  left: 10px;
}

.mes_block {
  padding: 0;
  overflow: visible;
  transform: none !important;
  display: flex;
  flex-direction: column;
}

.mes[is_user="true"] .mes_text {
  align-self: center;
}
.mes_text {
  padding: 0;
  text-align: justify;
}

.mes[is_user="true"] p:last-child {
  margin-bottom: 0;
}

.mes_text p:empty,
.mes_text p:has(> br:only-child),
.mes_text p:has(> content:only-child),
.mes_text p:has(> content > br:only-child) {
  display: none;
}

.mes_button,
.mes_edit_buttons {
  font-size: calc(var(--mainFontSize) * 1.01);
  filter: none !important;
  color: var(--SmartThemeBorderColor);
}

.mes .menu_button {
  opacity: 1;
  transform: scale(0.85);
  border-radius: 8px;
}

.swipe_right,
.swipe_left {
  opacity: 0.75;
  color: var(--SmartThemeBorderColor);
  font-size: 1.2em;
}

.swipe_right::before {
  content: "\f101";
}

.swipe_left::before {
  content: "\f100";
 }

/* by KAKAA */
.swipeRightBlock {
  flex-direction: row-reverse;
  bottom: calc(var(--swipeCounterHeight) + var(--swipeCounterMargin));
  margin-right: 15px; /* 左右位置 */
}

.swipeRightBlock:not(.last_mes .swipeRightBlock) {
   pointer-events: none;
}

.swipes-counter {
  transform: translate(25%, 20%);
}

.mes[is_user="false"] .ch_name {
  order: 1;
}

.mes[is_user="false"] .flex-container.alignItemsBaseline {
  position: absolute;
  top: 20px;
  left: 75px;
}

.mes[is_user="true"] .flex-container.alignItemsBaseline {
  position: absolute;
  bottom: 15px;
  left: 10px;
}

.mesAvatarWrapper {
  display: flex;
  align-items: flex-end;
  gap: 15px;
}

.mes[is_user="true"] .mesAvatarWrapper {
  align-self: flex-end;
  order: 1;
}

.mes[is_user="true"] .avatar {
  order: 1;
}

.last_mes .mesAvatarWrapper {
  padding-bottom: 0;
}

/* 全局头像 */
.avatar img,
body.big-avatar .avatar img{
  box-shadow: none;
  border: none;
}

.mes .avatar {
  transform: scale(0.75);
}

.mes .avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* --- 楼层 + 计时器 + tokens --- */
.mesIDDisplay:empty,
.mes_timer:empty,
.tokenCounterDisplay:empty {
  display: none !important;
}

.mes .mesIDDisplay,
.mes .mes_timer,
.mes .tokenCounterDisplay {
  opacity: 0.75;
  font-size: calc(var(--mainFontSize) * 0.75);
  margin-bottom: 15px;
}

/* ===== 菜单抽屉 ===== */
/* 缩小锁定图标 */
#rm_button_characters,
#rm_button_panel_pin_div,
#lm_button_panel_pin_div,
#WI_button_panel_pin_div {
  font-size: calc(var(--mainFontSize) *1.2);
}

/* 反代警告 */
.reverse_proxy_warning {
    border-color: crimson !important;
    border-radius: 2px !important;
    background-color: transparent !important;
}

/* 可移动UI预设 */
#movingUIPresets{
  margin-bottom: 0 !important;
}

/* --- 抽屉页背景 --- */
body .drawer-content {
  box-shadow: none;
  border-radius: 0 0 8px 8px;
  border-color: var(--SmartThemeBlurTintColor);
  border-bottom: 1px solid var(--SmartThemeBorderColor);
  background: url("https://files.catbox.moe/gvfian.png"),
    #fff;
  background-size: cover;
  background-repeat: no-repeat;
}

/* 预设页 & 角色管理页 */
@media (max-width: 600px) {
  #left-nav-panel,
  #right-nav-panel {
    max-height: calc(100dvh - var(--topBarBlockSize));
    border-radius: 0 0 8px 8px;
    border-color: var(--SmartThemeBlurTintColor);
    border-bottom: 1px solid var(--SmartThemeBorderColor);
    padding-right: 0;
  }
}

/* --- 标题栏 --- */
.standoutHeader,
.inline-drawer-header,
#theme-manager-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header, 
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4:not(#theme-manager-header h4),
#top-settings-holder h4:not(#ai-config-button):not(#rightNavHolder):not(#theme-manager-header h4) {
  padding: 5px 8px;
  margin-bottom: 8px;
  border-radius: 5px;
  border: 0.5px solid var(--SmartThemeBorderColor);
  background:
    radial-gradient(55% 105% ellipse at left top, rgba(90, 175, 87, 0.45), transparent),
    radial-gradient(35% 60% ellipse at 65% 110%, rgba(237, 255, 225, 0.5), transparent),
    radial-gradient(120px circle at right center, rgba(118, 171, 139, 0.43), transparent),
    rgba(199, 227, 205, 1);
  box-shadow:
    0.5px 0.5px 0 0.7px rgba(146, 203, 152, 0.25),
    inset 0 0 12px rgba(255, 255, 255, 0.25),
    inset 0 0 4px rgba(255, 255, 255, 0.75);
  filter: 
    drop-shadow(1px 1px 1px rgba(206, 250, 208, 0.15))
    drop-shadow(0 0 1px rgba(109, 138, 110, 0.25))
    drop-shadow(0 0 2px rgba(132, 164, 136, 0.15)) !important;
}

/* 箭头 */
.inline-drawer-icon {
  color: var(--混合);
  filter: drop-shadow(0 0 12px var(--SmartThemeBorderColor));
  font-size: 1.1em;
}

/* 闭合状态 */
.inline-drawer-icon::before {
  content: "🌱" !important;
}

/* 展开状态 */
.inline-drawer-icon.up::before {
  content: "🌲" !important;
}

/* --- 按钮 --- */
.menu_button:not(.mes_edit_buttons *) {
  box-shadow: 
    1px 1px 1px var(--混合),
    inset 0 0 15px var(--SmartThemeBlurTintColor);
  background-color: color-mix(in srgb, var(--SmartThemeBorderColor) 20%, white);
  color: var(--SmartThemeBorderColor);
  border: none;
  filter: none !important;
}

#ddelete_button,
#dialogue_del_mes_ok,
#dialogue_popup_ok,
#bulk_tag_popup_reset,
#bulk_tag_popup_remove_mutual,
.mes_edit_cancel.menu_button,
.menu_button.popup-button-ok,
.redWarningBG {
  background: crimson !important;
  color: black !important;
}

/* --- 勾选框 --- */
input[type="checkbox"] {
  background: var(--SmartThemeBlurTintColor);
  border-radius: 3px;
  filter: none;
  border: none;
  outline: none;
  box-shadow: inset 0 0 4px var(--混合) !important;
}

.checkbox_label {
  display: flex;
  align-items: center;
}

input[type="checkbox"]:checked {
  background: rgba(150, 196, 157, 0.65) !important;
  box-shadow: inset 0 0 4px var(--SmartThemeBlurTintColor) !important;
}

/* --- 下拉框 --- */
#character_sort_order,
select.text_pole,
select {
  outline: none !important;
  border: none;
  border-radius: 5px;
  box-shadow: 
    1px 1px 2.5px var(--混合),
    inset 0 0 15px var(--SmartThemeBlurTintColor);
  background-color: color-mix(in srgb, var(--SmartThemeBorderColor) 35%, #fff);
}

#tag_import_setting {
  margin-top: 5px;
}

select {
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path fill="%23B4D1BE" d="M5.5 7l4.5 4.5 4.5-4.5 1.5 1.5-6 6-6-6z"/></svg>');
  background-position: right 4px center;
  background-repeat: no-repeat;
  background-size: 16px;
  cursor: pointer;
}

/* 移除 IE 的默认箭头 */
select::-ms-expand {
  display: none;
}

/* --- 输入框 --- */
/* 搜索框 + 部分输入框 */
#settingsSearch.textarea_compact,
.text_pole:not(.objective-task):not(select) {
  border: none;
  border-radius: 5px;
  box-shadow: 
    1px 1px 2.5px var(--混合),
    inset 0 0 25px var(--SmartThemeBlurTintColor);
  background: color-mix(in srgb, var(--SmartThemeBorderColor) 30%, #fff);
}

input[type="text"],
input[type="number"],
input[type="switch"],
input:not([type]),
textarea:not([type="search"]) {
  outline: none !important;
  border: none;
  background: color-mix(in srgb, var(--SmartThemeBorderColor) 25%, #fff);
  box-shadow: 
    1px 1px 2.5px var(--混合),
    inset 0 0 5px var(--SmartThemeBlurTintColor);
}

/* --- 弹窗 --- */
#character_popup, 
#dialogue_popup,
.draggable,        
#select_chat_popup, 
.popup:not(.transparent_dialogue_popup) { 
    border-radius: 5px;
    border: none;
    box-shadow: 
      inset 0 0 15px var(--SmartThemeBlurTintColor),
      1px 1px 5px rgba(55,55,55,0.08),
      0 0 6px var(--混合) !important;
  background: url("https://files.catbox.moe/gvfian.png"),
    #fff;
  background-size: cover;
  background-repeat: no-repeat;
}

/* 对话弹出窗文本 */
#dialogue_popup_text {
    padding-right: 5px;
}

/* 给'提示词拆分'添加滚动条 */
.popup-content:has(#showRawPrompt) {
    overflow-y: auto;
}

/* 通知提示框 */
div.toast.toast-success {
  background-color: var(--混合) !important;
  border-radius: 2px !important;
  color: var(--SmartThemeBodyColor) !important;
  box-shadow: inset 0 0 15px var(--SmartThemeBlurTintColor),
    1px 1px 5px rgba(55,55,55,0.1),
    0 0 6px var(--混合) !important;
}

/* --- 预设页 --- */
#range_block_openai .range-block .toggle-description {
  margin-right: 0;
}

.range-block-title {
  text-align: left;
}

label[for="openai_image_inlining"] + div, 
#openai_settings .inline-drawer-header .flex-container {
  gap: 0;
  text-align: left;
}

/* --- 提示词管理器 --- */
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
  filter: none;
}

#completion_prompt_manager .completion_prompt_manager_header {
  padding: 0;
}

.completion_prompt_manager_footer {
