}

.character_select.is_fav .avatar {
  outline: 2px solid var(--混合);
}

.character_select.is_fav .ch_name {
  border-radius: 20px;
  max-width: 50%;
  padding: 0 10px;
  background: var(--混合);
  color: var(--SmartThemeQuoteColor);
  box-shadow:
    0 0 4px var(--混合),
    inset 0 0 8px rgba(255, 255, 255, 0.75);
}

